#include <iostream>
#include <climits>

struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int val) : data(val), left(nullptr), right(nullptr) {}
};

bool isValidBSTHelper(Node* root, long minVal, long maxVal) {
    if (root == nullptr) return true; // Empty tree is valid

    // Check if current node violates the range bounds
    if (root->data <= minVal || root->data >= maxVal) {
        return false;
    }

    // Recurse left (updating max constraint) and right (updating min constraint)
    return isValidBSTHelper(root->left, minVal, root->data) &&
           isValidBSTHelper(root->right, root->data, maxVal);
}

bool isValidBST(Node* root) {
    return isValidBSTHelper(root, LONG_MIN, LONG_MAX);
}
